/**
 * The github workflow templates of pob:core:ci, rendered to the exact string
 * ejs produced, before oxfmt. The release-please branches are not ported:
 * `isReleasePleaseEnabled` was never set.
 */
/* oxlint-disable eslint/no-template-curly-in-string -- github actions expressions */
import type { PackageManager } from "../../engine/config.ts";
import { escapeHtml as e } from "./escapeHtml.ts";

const header = [
  "# Generated by pob: do not edit, it is overwritten on each pob run.",
];

const lines = (content: readonly string[]): string => `${content.join("\n")}\n`;

const setupPackageManager = (packageManager: PackageManager): string[] => {
  switch (packageManager) {
    case "yarn":
      return [
        "      - name: Enable Corepack",
        "        run: corepack enable",
        "",
      ];
    case "bun":
      return [
        "      - name: Install bun",
        "        uses: oven-sh/setup-bun@v2",
        "        with:",
        "          bun-version: latest",
        "",
      ];
    case "pnpm":
      return [
        "      - name: Install pnpm",
        "        uses: pnpm/action-setup@v6",
        "",
      ];
    case "npm":
      return [];
    default:
      throw new Error(`Unsupported package manager: ${String(packageManager)}`);
  }
};

const yarnInstall = (disableYarnGitCache: boolean): string =>
  disableYarnGitCache
    ? "        run: yarn install --immutable"
    : "        run: yarn install --immutable --immutable-cache";

const installCommands: Record<PackageManager, string> = {
  yarn: "",
  npm: "        run: npm ci",
  bun: "        run: bun install --frozen-lockfile",
  pnpm: "        run: pnpm install --frozen-lockfile",
};

interface InstallOptions {
  packageManager: PackageManager;
  disableYarnGitCache: boolean;
  /** whether the template had an npm branch */
  withNpm: boolean;
}

/** "Install Dependencies" step, its name repeated in each branch */
const namedInstall = ({
  packageManager,
  disableYarnGitCache,
  withNpm,
}: InstallOptions): string[] => {
  if (packageManager === "npm" && !withNpm) return [];
  return [
    "      - name: Install Dependencies",
    packageManager === "yarn"
      ? yarnInstall(disableYarnGitCache)
      : installCommands[packageManager],
  ];
};

/** "Install Dependencies" step, its name before the branches */
const install = ({
  packageManager,
  disableYarnGitCache,
  withNpm,
}: InstallOptions): string[] => {
  const command = (() => {
    if (packageManager === "yarn") return yarnInstall(disableYarnGitCache);
    if (packageManager === "npm" && !withNpm) return undefined;
    return installCommands[packageManager];
  })();
  return ["      - name: Install Dependencies", ...(command ? [command] : [])];
};

export interface PushWorkflowOptions {
  packageManager: PackageManager;
  disableYarnGitCache: boolean;
  testing: boolean;
  testRunner: string | undefined;
  /** "" for none */
  e2eTesting: string;
  checks: boolean;
  build: boolean;
  typescript: boolean;
  codecov: boolean;
  nodeMajorVersions: string[];
  nodeLatestMajorVersion: string;
  installPlaywrightBrowserCommand: string;
  mongodbBinaryCacheKeyFile: string;
  packageManagerRun: (script: string, packagePath?: string) => string;
  packageManagerExec: (command: string) => string;
}

const mongodbCache = (mongodbBinaryCacheKeyFile: string): string[] => [
  "      - name: Cache mongod binary",
  "        uses: actions/cache@v6",
  "        with:",
  "          path: ~/.cache/mongodb-binaries",
  `          key: mongod-\${{ runner.os }}-\${{ hashFiles('${e(mongodbBinaryCacheKeyFile)}') }}`,
];

/** github-action-push-workflow.yml.ejs */
export const renderPushWorkflow = (options: PushWorkflowOptions): string => {
  const pm = e(options.packageManager);
  const ifLatest = `        if: startsWith(matrix.node-version, '${e(options.nodeLatestMajorVersion)}.')`;
  const withTests = options.codecov || options.testing;
  const testSteps = (() => {
    if (options.codecov) {
      return [
        "",
        "      - name: Generate Test Coverage",
        `        run: ${e(options.packageManagerRun("test:coverage:generate"))}`,
        ifLatest,
        "        env:",
        "          CI: true",
        "",
        "      - name: Send results to codecov",
        "        uses: codecov/codecov-action@v7",
        "        with:",
        "          fail_ci_if_error: true",
        "          token: ${{ secrets.CODECOV_TOKEN }}",
        `          files: ${options.testRunner === "node" ? "./generated-docs/coverage.lcov" : "./coverage/coverage-final.json"}`,
        "          disable_search: true",
        `        if: startsWith(matrix.node-version, '${e(options.nodeLatestMajorVersion)}.') && github.actor != 'dependabot[bot]'`,
      ];
    }
    if (options.testing) {
      return [
        "",
        "      - name: Test",
        `        run: ${pm} run test`,
        "        env:",
        "          CI: true",
      ];
    }
    return [];
  })();
  return lines([
    ...header,
    "name: Push CI",
    "permissions:",
    "  contents: read",
    "on: [push]",
    "",
    "jobs:",
    "  build:",
    "    runs-on: ubuntu-latest",
    "",
    "    strategy:",
    "      matrix:",
    `        node-version: [${e(options.nodeMajorVersions.map((version) => `${version}.x`).join(", "))}]`,
    "",
    "    steps:",
    "      - uses: actions/checkout@v7",
    "",
    ...setupPackageManager(options.packageManager),
    "      - name: Use Node.js ${{ matrix.node-version }}",
    "        uses: actions/setup-node@v7",
    "        with:",
    "          node-version: ${{ matrix.node-version }}",
    "          registry-url: 'https://registry.npmjs.org'",
    "",
    ...namedInstall({ ...options, withNpm: true }),
    "",
    ...(options.checks
      ? ["      - name: Checks", `        run: ${pm} run checks`, ifLatest, ""]
      : []),
    ...(options.build
      ? ["      - name: Build", `        run: ${pm} run build`, ""]
      : []),
    "      - name: Format",
    `        run: ${pm} run format:check`,
    ifLatest,
    ...(options.typescript
      ? ["", "      - name: Typescript", `        run: ${pm} run tsc`, ifLatest]
      : []),
    "",
    "      - name: Oxlint",
    `        run: ${pm} run lint:oxlint`,
    ifLatest,
    "",
    "      - name: Eslint",
    `        run: ${pm} run lint:eslint`,
    ifLatest,
    "",
    "      - name: Check nothing was forgotten before commit",
    ifLatest,
    `        run: ${e(options.packageManagerExec("repository-check-dirty"))}`,
    ...(withTests && options.installPlaywrightBrowserCommand
      ? [
          "",
          "      - name: Install Playwright chromium",
          `        run: ${options.installPlaywrightBrowserCommand}`,
        ]
      : []),
    ...(withTests && options.mongodbBinaryCacheKeyFile
      ? ["", ...mongodbCache(options.mongodbBinaryCacheKeyFile)]
      : []),
    ...testSteps,
    ...(options.e2eTesting
      ? [
          "",
          "      - name: E2E testing prepare",
          `        run: ${e(options.packageManagerRun("test:e2e:prepare", options.e2eTesting))}`,
          ifLatest,
          "",
          "      - name: E2E testing",
          `        run: ${e(options.packageManagerRun("test:e2e", options.e2eTesting))}`,
          ifLatest,
        ]
      : []),
  ]);
};

interface SplitJobOptions {
  name: string;
  options: PushWorkflowOptions;
  nodeVersion: string;
  withNpm: boolean;
}

const splitJobStart = ({
  name,
  options,
  nodeVersion,
  withNpm,
}: SplitJobOptions): string[] => [
  `  ${name}:`,
  "    runs-on: ubuntu-latest",
  "",
  "    steps:",
  "      - uses: actions/checkout@v7",
  "",
  ...setupPackageManager(options.packageManager),
  "      - uses: actions/setup-node@v7",
  "        with:",
  `          node-version: ${nodeVersion}`,
  "",
  ...install({ ...options, withNpm }),
];

/** github-action-push-workflow-split.yml.ejs */
export const renderPushWorkflowSplit = (
  options: PushWorkflowOptions,
): string => {
  const run = (script: string, packagePath?: string): string =>
    e(options.packageManagerRun(script, packagePath));
  const latest = e(options.nodeLatestMajorVersion);
  const buildStep = options.build
    ? ["", "      - name: Build", `        run: ${run("build")}`]
    : [];
  const testJob = (): string[] => [
    "",
    "  test:",
    "    runs-on: ubuntu-latest",
    "",
    "    strategy:",
    "      matrix:",
    `        node-version: [${e(options.nodeMajorVersions.join(", "))}]`,
    "",
    "    steps:",
    "      - uses: actions/checkout@v7",
    "",
    ...setupPackageManager(options.packageManager),
    "      - uses: actions/setup-node@v7",
    "        with:",
    "          node-version: ${{ matrix.node-version }}",
    "",
    ...namedInstall({ ...options, withNpm: false }),
    ...buildStep,
    ...(options.installPlaywrightBrowserCommand
      ? [
          "",
          "      - name: Install Playwright chromium",
          `        run: ${options.installPlaywrightBrowserCommand}`,
        ]
      : []),
    ...(options.mongodbBinaryCacheKeyFile
      ? ["", ...mongodbCache(options.mongodbBinaryCacheKeyFile)]
      : []),
    "",
    ...(options.codecov
      ? [
          "      - name: Test",
          `        run: ${run("test")}`,
          `        if: matrix.node-version != ${latest}`,
          "",
          "      - name: Generate Test Coverage",
          `        run: ${run("test:coverage:generate")}`,
          `        if: matrix.node-version == ${latest}`,
          "        env:",
          "          CI: true",
          "",
          "      - name: Send results to codecov",
          "        uses: codecov/codecov-action@v7",
          `        if: matrix.node-version == ${latest} && github.actor != 'dependabot[bot]'`,
          "        with:",
          "          fail_ci_if_error: true",
          "          token: ${{ secrets.CODECOV_TOKEN }}",
        ]
      : ["", "      - name: Test", `        run: ${run("test")}`]),
  ];
  return lines([
    ...header,
    "name: Push CI",
    "permissions:",
    "  contents: read",
    "on: [push]",
    "",
    "jobs:",
    ...(options.checks
      ? [
          ...splitJobStart({
            name: "checks",
            options,
            nodeVersion: latest,
            withNpm: false,
          }),
          "",
          "      - name: Checks",
          `        run: ${run("checks")}`,
          "",
        ]
      : []),
    ...(options.build
      ? [
          ...splitJobStart({
            name: "build",
            options,
            nodeVersion: latest,
            withNpm: false,
          }),
          "",
          "      - name: Build",
          `        run: ${run("build")}`,
          "",
          "      - name: Check nothing was forgotten before commit",
          `        run: ${e(options.packageManagerExec("repository-check-dirty"))}`,
          "",
        ]
      : []),
    ...splitJobStart({
      name: "lint",
      options,
      nodeVersion: latest,
      withNpm: true,
    }),
    ...buildStep,
    "",
    "      - name: Format",
    `        run: ${run("format:check")}`,
    ...(options.typescript
      ? ["", "      - name: Typescript", `        run: ${run("tsc")}`]
      : []),
    "",
    "      - name: Oxlint",
    `        run: ${run("lint:oxlint")}`,
    "",
    "      - name: Eslint",
    `        run: ${run("lint:eslint")}`,
    ...(options.testing ? testJob() : []),
    ...(options.e2eTesting
      ? [
          "",
          "  test-e2e:",
          "    runs-on: ubuntu-latest",
          "",
          "    strategy:",
          "      matrix:",
          `        node-version: [${latest}]`,
          "",
          "    steps:",
          "      - uses: actions/checkout@v7",
          "",
          ...setupPackageManager(options.packageManager),
          "      - uses: actions/setup-node@v7",
          "        with:",
          "          node-version: ${{ matrix.node-version }}",
          "",
          ...install({ ...options, withNpm: true }),
          ...buildStep,
          "",
          "      - name: E2E testing prepare",
          `        run: ${run("test:e2e:prepare", options.e2eTesting)}`,
          "",
          "      - name: E2E testing",
          `        run: ${run("test:e2e", options.e2eTesting)}`,
        ]
      : []),
  ]);
};

export interface DocumentationWorkflowOptions {
  packageManager: PackageManager;
  disableYarnGitCache: boolean;
  build: boolean;
  typedoc: boolean;
  nodeLatestMajorVersion: string;
}

/** github-action-documentation-workflow.yml.ejs */
export const renderDocumentationWorkflow = (
  options: DocumentationWorkflowOptions,
): string => {
  const pm = e(options.packageManager);
  return lines([
    ...header,
    "name: 'Create documentation and deploy to Github pages'",
    "on:",
    "  push:",
    "    branches:",
    "      - main",
    "",
    "jobs:",
    "  create-documentation-and-deploy:",
    "    runs-on: ubuntu-latest",
    "    steps:",
    "      - uses: actions/checkout@v7",
    "",
    ...setupPackageManager(options.packageManager),
    "      - uses: actions/setup-node@v7",
    "        with:",
    `          node-version: ${e(options.nodeLatestMajorVersion)}`,
    "",
    ...namedInstall({ ...options, withNpm: false }),
    ...(options.build
      ? ["", "      - name: Build", `        run: ${pm} run build`]
      : []),
    "",
    ...(options.typedoc
      ? [
          "      - name: Run tsc for tsc cache",
          `        run: ${pm} tsc`,
          "",
          "      - name: Generate Typedoc",
          `        run: ${pm} typedoc --tsconfig tsconfig.doc.json`,
        ]
      : []),
    "",
    "      - name: Create nojekyll",
    "        run: touch generated-docs/.nojekyll",
    "",
    "      - name: Deploy",
    "        uses: peaceiris/actions-gh-pages@v4",
    "        with:",
    "          github_token: ${{ secrets.GITHUB_TOKEN }}",
    "          publish_dir: ./generated-docs",
  ]);
};
